const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.spoken=[];window.speak=s=>{if(s)spoken.push(s)};window.tone=()=>{}});await p.click('#learningTab');
await p.click('#alStart');if(await p.locator('.greeting-welcome').count()!==1||await p.locator('.al-word').count()!==6)throw Error('New learner does not begin with six greeting cards');if(await p.evaluate(()=>spoken.length))throw Error('Intro autoplay');await p.locator('[data-greeting-audio="0"]').click();if(!await p.evaluate(()=>spoken[0]==='Hallo!'))throw Error('Greeting playback not exact');
await p.evaluate(()=>{for(const p of DEUTSCH_GREETINGS.phrases){if(recordedAudioFiles(p[0])?.length!==1)throw Error('Missing whole recording '+p[0])}if(DEUTSCH_PROGRESS.snapshot().answers!==0)throw Error('Opening recorded study activity');sessionStorage.setItem('beforeGreetings',JSON.stringify(DEUTSCH_JOURNEY.load()));});
for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Greeting overflow '+width)}fs.mkdirSync('audit-screenshots',{recursive:true});await p.setViewportSize({width:390,height:1000});await p.screenshot({path:'audit-screenshots/greetings-intro.png',fullPage:true});
const solve=async(correct=true)=>{await p.click('#greetingBegin');for(let at=0;at<14;at++){const expected=at<6?at:[0,1,2,3,4,5,0,4][at-6];await p.evaluate(({expected,correct})=>{const bs=[...document.querySelectorAll('[data-greeting-choice]')];const b=bs.find(b=>correct?+b.dataset.greetingChoice===expected:+b.dataset.greetingChoice!==expected);b.click();const before=document.querySelector('#greetingFeedback').innerHTML;b.click();if(document.querySelector('#greetingFeedback').innerHTML!==before)throw Error('Double answer mutated feedback')},{expected,correct});if(at===9)await p.screenshot({path:'audit-screenshots/greetings-evening-task.png',fullPage:true});await p.click('#greetingNext');}};
await solve(false);if(!await p.evaluate(()=>DEUTSCH_PROGRESS.snapshot().answers===14&&DEUTSCH_REVIEW.snapshot().data.history.length===14))throw Error('Answers missing or counted twice in activity/review');if(await p.locator('[data-greeting-result="retry"]').count()!==1||await p.evaluate(()=>DEUTSCH_GREETINGS.read().passed))throw Error('Failed prologue awarded completion');await p.click('#greetingRetry');await solve();if(!await p.evaluate(()=>DEUTSCH_GREETINGS.read().passed&&DEUTSCH_GREETINGS.read().best===8&&JSON.stringify(DEUTSCH_JOURNEY.load())===sessionStorage.getItem('beforeGreetings')))throw Error('Completion or journey compatibility failed');await p.click('#greetingContinue');if(!await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().journey.index===0))throw Error('No first mission continuation');await p.evaluate(()=>DEUTSCH_JOURNEY.map());await p.click('#greetingOpen');await solve(false);if(!await p.evaluate(()=>DEUTSCH_GREETINGS.read().passed&&DEUTSCH_GREETINGS.read().best===8))throw Error('Retry erased completion');await p.reload();await p.evaluate(()=>{window.spoken=[];window.speak=s=>{if(s)spoken.push(s)};window.tone=()=>{}});await p.click('#learningTab');if(await p.locator('[data-greeting-prologue="passed"]').count()!==1)throw Error('Completion lost on reload');
await p.evaluate(()=>{DEUTSCH_JOURNEY.open(1);sessionStorage.setItem('campBefore',JSON.stringify(DEUTSCH_JOURNEY.load()))});await p.click('#campGreetings');if(await p.locator('.al-word').count()!==2)throw Error('Camp must contrast two phrases');await p.locator('#learningView img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.click('#greetingBegin');for(const target of [3,6]){await p.click('[data-greeting-choice="'+target+'"]');await p.click('#greetingNext')}await p.click('#greetingContinue');if(!await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().journey.index===1&&JSON.stringify(DEUTSCH_JOURNEY.load())===sessionStorage.getItem('campBefore')))throw Error('Camp changed mission/progress');
await p.evaluate(()=>DEUTSCH_JOURNEY.select(1));if(await p.locator('[data-greeting-prologue]').count())throw Error('Wrong island card');await p.evaluate(()=>DEUTSCH_JOURNEY.open(0));await p.locator('[data-journey-greeting]').click();if(!await p.evaluate(()=>spoken.at(-1)==='Guten Morgen!'))throw Error('Village greeting missing');await p.click('#alContinue');await p.evaluate(()=>{while(!DEUTSCH_ADAPTIVE.snapshot().finished)DEUTSCH_ADAPTIVE.skip()});if(!await p.locator('[data-journey-greeting="Auf Wiedersehen!"]').count())throw Error('Village goodbye missing');
await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.select(0);DEUTSCH_JOURNEY.greetings()});if(!await p.locator('h1').textContent().then(x=>x.includes('Meeting on the shore')))throw Error('English missing');await p.click('#profileButton');await p.fill('#profileAddInput','Greeting child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');if(await p.evaluate(()=>DEUTSCH_GREETINGS.read()))throw Error('Completion leaked between profiles');if(errors.length)throw Error(errors.join(';'));console.log('PASS greeting prologue, whole recordings, art, responsive UI, practice, contextual test, dialogue, retention, camp contrast, village continuity, English and profiles');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
